namespace photomode {
namespace {
constexpr UvRect kFullUv{0, 0, 1, 1};
template <typename T>
void SafeRelease(T*& p) {
  if (p) {
    p->Release();
    p = nullptr;
  }
}

// fp32 is exact enough for any sample count; fp16 still works for a preview-quality mean.
D3DFORMAT PickAccumFormat(IDirect3DDevice9* dev) {
  IDirect3D9* d3d = nullptr;
  D3DDEVICE_CREATION_PARAMETERS cp{};
  D3DDISPLAYMODE dm{};
  D3DFORMAT fmt = D3DFMT_UNKNOWN;
  if (SUCCEEDED(dev->GetDirect3D(&d3d)) && SUCCEEDED(dev->GetCreationParameters(&cp)) &&
      SUCCEEDED(dev->GetDisplayMode(0, &dm))) {
    for (D3DFORMAT f : {D3DFMT_A32B32G32R32F, D3DFMT_A16B16G16R16F})
      if (SUCCEEDED(d3d->CheckDeviceFormat(cp.AdapterOrdinal, cp.DeviceType, dm.Format, D3DUSAGE_RENDERTARGET,
                                           D3DRTYPE_TEXTURE, f))) {
        fmt = f;
        break;
      }
  }
  SafeRelease(d3d);
  return fmt;
}

// Everything AddSample/Show set on the device. Recorded once into a state block; Capture() before
// our draws and Apply() after put the game's values back. The device is created with
// D3DCREATE_PUREDEVICE (0x50 at 0x5B9B89), so we cannot Get* these states one by one. The game
// itself rebinds RT/DS/viewport and resets the core render states at the start of the 2D pass
// right after Render3D (0x5CBF40 -> 0x5C2430), but blend/shader/texture states are not reset there.
void SetOurStates(IDirect3DDevice9* dev) {
  dev->SetVertexShader(nullptr);
  dev->SetPixelShader(nullptr);
  dev->SetFVF(D3DFVF_XYZRHW | D3DFVF_TEX1);
  const float zero[4] = {};
  dev->SetPixelShaderConstantF(0, zero, 1);
  for (DWORD s = 0; s < 2; ++s) {
    dev->SetTexture(s, nullptr);
    dev->SetSamplerState(s, D3DSAMP_MINFILTER, D3DTEXF_POINT);
    dev->SetSamplerState(s, D3DSAMP_MAGFILTER, D3DTEXF_POINT);
    dev->SetSamplerState(s, D3DSAMP_MIPFILTER, D3DTEXF_NONE);
    dev->SetSamplerState(s, D3DSAMP_ADDRESSU, D3DTADDRESS_CLAMP);
    dev->SetSamplerState(s, D3DSAMP_ADDRESSV, D3DTADDRESS_CLAMP);
    dev->SetSamplerState(s, D3DSAMP_SRGBTEXTURE, FALSE);
  }
  dev->SetRenderState(D3DRS_ALPHABLENDENABLE, FALSE);
  dev->SetRenderState(D3DRS_ALPHATESTENABLE, FALSE);
  dev->SetRenderState(D3DRS_ZENABLE, D3DZB_FALSE);
  dev->SetRenderState(D3DRS_ZWRITEENABLE, FALSE);
  dev->SetRenderState(D3DRS_STENCILENABLE, FALSE);
  dev->SetRenderState(D3DRS_CULLMODE, D3DCULL_NONE);
  dev->SetRenderState(D3DRS_COLORWRITEENABLE, 0xF);
  dev->SetRenderState(D3DRS_SCISSORTESTENABLE, FALSE);
  dev->SetRenderState(D3DRS_FOGENABLE, FALSE);
  dev->SetRenderState(D3DRS_SRGBWRITEENABLE, FALSE);
  D3DVIEWPORT9 vp{0, 0, 1, 1, 0, 1};
  dev->SetViewport(&vp);
}
}  // namespace

bool Accum::Ensure(IDirect3DDevice9* dev) {
  D3DSURFACE_DESC d;
  if (failed_ || !u2::d3d::BackBufferDesc(dev, &d)) return false;
  return Ensure(dev, static_cast<int>(d.Width), static_cast<int>(d.Height));
}

bool Accum::Ensure(IDirect3DDevice9* dev, int w, int h) {
  if (failed_ || !dev) return false;
  if (scene_ && w == width_ && h == height_) return true;
  Release();
  count_ = 0;
  return Create(dev, w, h);
}

bool Accum::Create(IDirect3DDevice9* dev, int w, int h) {
  D3DFORMAT fmt = PickAccumFormat(dev);
  if (fmt == D3DFMT_UNKNOWN) {
    Fail("no float render-target format", 0);
    return false;
  }
  HRESULT hr;
  if (FAILED(hr = dev->CreateTexture(w, h, 1, D3DUSAGE_RENDERTARGET, D3DFMT_X8R8G8B8, D3DPOOL_DEFAULT, &scene_, nullptr)) ||
      FAILED(hr = dev->CreateTexture(w, h, 1, D3DUSAGE_RENDERTARGET, fmt, D3DPOOL_DEFAULT, &acc_[0], nullptr)) ||
      FAILED(hr = dev->CreateTexture(w, h, 1, D3DUSAGE_RENDERTARGET, fmt, D3DPOOL_DEFAULT, &acc_[1], nullptr))) {
    Fail("CreateTexture", hr);
    return false;
  }
  // DEFAULT-pool memory is undefined (possibly NaN/Inf as fp32): start from black.
  for (IDirect3DTexture9* t : acc_) {
    IDirect3DSurface9* s = nullptr;
    if (SUCCEEDED(hr = t->GetSurfaceLevel(0, &s))) {
      hr = dev->ColorFill(s, nullptr, 0);
      s->Release();
    }
    if (FAILED(hr)) {
      Fail("ColorFill", hr);
      return false;
    }
  }
  if (FAILED(hr = dev->CreatePixelShader(reinterpret_cast<const DWORD*>(g_ps_accum), &psAccum_)) ||
      FAILED(hr = dev->CreatePixelShader(reinterpret_cast<const DWORD*>(g_ps_show), &psShow_)) ||
      FAILED(hr = dev->CreatePixelShader(reinterpret_cast<const DWORD*>(g_ps_show2x), &psShow2x_)) ||
      FAILED(hr = dev->CreatePixelShader(reinterpret_cast<const DWORD*>(g_ps_copy), &psCopy_))) {
    Fail("CreatePixelShader", hr);
    return false;
  }
  if (FAILED(hr = dev->BeginStateBlock())) {
    Fail("BeginStateBlock", hr);
    return false;
  }
  SetOurStates(dev);
  if (FAILED(hr = dev->EndStateBlock(&state_))) {
    Fail("EndStateBlock", hr);
    return false;
  }
  width_ = w;
  height_ = h;
  cur_ = 0;
  U2LOG("%s: %dx%d %s, state block ok", name_, w, h, fmt == D3DFMT_A32B32G32R32F ? "fp32" : "fp16");
  return true;
}

void Accum::Draw(IDirect3DDevice9* dev, IDirect3DSurface9* target, IDirect3DPixelShader9* ps, IDirect3DTexture9* t0,
                 IDirect3DTexture9* t1, const float c0[4], const UvRect& uv) {
  // The quad covers the whole target, whatever the accumulator's own size.
  D3DSURFACE_DESC td;
  target->GetDesc(&td);
  const float x1 = static_cast<float>(td.Width) - 0.5f, y1 = static_cast<float>(td.Height) - 0.5f;
  const Quad q{-0.5f, -0.5f, x1, y1, uv.u0, uv.v0, uv.u1, uv.v1};
  DrawQuads(dev, target, ps, t0, t1, c0, &q, 1);
}

void Accum::ShowKeptPieces(IDirect3DDevice9* dev, const edges::Piece* pieces, int count) {
  if (failed_ || !kept_) return;
  IDirect3DSurface9* rt = nullptr;
  if (FAILED(dev->GetRenderTarget(0, &rt))) return;
  // The kept frame is screen-sized: each piece pixel samples its own texel centre, 1:1, moved.
  const float du = 1.0f / width_, dv = 1.0f / height_;
  Quad q[edges::kPieces];
  const int n = count < edges::kPieces ? count : edges::kPieces;
  for (int i = 0; i < n; ++i) {
    const edges::Piece& p = pieces[i];
    q[i] = {p.dx - 0.5f, p.dy - 0.5f, p.dx + p.w - 0.5f, p.dy + p.h - 0.5f,
            p.sx * du, p.sy * dv, (p.sx + p.w) * du, (p.sy + p.h) * dv};
  }
  const float zero[4] = {};
  DrawQuads(dev, rt, psCopy_, kept_, nullptr, zero, q, n);
  rt->Release();
}

void Accum::Keep(IDirect3DDevice9* dev) {
  if (failed_ || !scene_) return;
  HRESULT hr = S_OK;
  if (!kept_ && FAILED(hr = dev->CreateTexture(width_, height_, 1, D3DUSAGE_RENDERTARGET, D3DFMT_X8R8G8B8,
                                               D3DPOOL_DEFAULT, &kept_, nullptr))) {
    Fail("Keep texture", hr);
    return;
  }
  CopyTarget(dev, kept_, "Keep");
}

void Accum::CopyTarget(IDirect3DDevice9* dev, IDirect3DTexture9* dst, const char* what) {
  IDirect3DSurface9 *rt = nullptr, *s = nullptr;
  HRESULT hr = dev->GetRenderTarget(0, &rt);
  if (SUCCEEDED(hr)) hr = dst->GetSurfaceLevel(0, &s);
  if (SUCCEEDED(hr)) hr = dev->StretchRect(rt, nullptr, s, nullptr, D3DTEXF_NONE);  // resolves MSAA too
  if (FAILED(hr)) Fail(what, hr);
  SafeRelease(rt);
  SafeRelease(s);
}

void Accum::DrawQuads(IDirect3DDevice9* dev, IDirect3DSurface9* target, IDirect3DPixelShader9* ps,
                      IDirect3DTexture9* t0, IDirect3DTexture9* t1, const float c0[4], const Quad* quads, int count) {
  D3DSURFACE_DESC td;
  target->GetDesc(&td);
  // Stream 0 and the render target are not part of the recorded block: save them as WidescreenFix
  // postfxcore.ixx SaveVertexState does (DrawPrimitiveUP resets stream 0).
  IDirect3DVertexBuffer9* vb = nullptr;
  UINT offset = 0, stride = 0;
  IDirect3DSurface9 *rt = nullptr, *ds = nullptr;
  dev->GetStreamSource(0, &vb, &offset, &stride);
  dev->GetRenderTarget(0, &rt);
  dev->GetDepthStencilSurface(&ds);
  HRESULT hr = state_->Capture();
  if (FAILED(hr)) {
    Fail("StateBlock::Capture", hr);
  } else {
    SetOurStates(dev);
    dev->SetRenderTarget(0, target);
    // With in-game FSAA the auto depth-stencil is multisampled and must not stay bound with our
    // non-MSAA targets; Z is off anyway. The 2D pass rebinds it next (0x5CBF40).
    dev->SetDepthStencilSurface(nullptr);
    D3DVIEWPORT9 vp{0, 0, td.Width, td.Height, 0, 1};
    dev->SetViewport(&vp);
    dev->SetPixelShader(ps);
    dev->SetPixelShaderConstantF(0, c0, 1);
    dev->SetTexture(0, t0);
    dev->SetTexture(1, t1);
    struct V { float x, y, z, rhw, u, v; };
    for (int i = 0; i < count; ++i) {
      const Quad& a = quads[i];
      const V q[4] = {{a.x0, a.y0, 0, 1, a.u0, a.v0}, {a.x1, a.y0, 0, 1, a.u1, a.v0},
                      {a.x0, a.y1, 0, 1, a.u0, a.v1}, {a.x1, a.y1, 0, 1, a.u1, a.v1}};
      dev->DrawPrimitiveUP(D3DPT_TRIANGLESTRIP, 2, q, sizeof(V));
    }
    dev->SetRenderTarget(0, rt);  // resets the viewport; Apply() below restores the game's
    dev->SetDepthStencilSurface(ds);
    state_->Apply();
  }
  dev->SetStreamSource(0, vb, offset, stride);
  SafeRelease(vb);
  SafeRelease(rt);
  SafeRelease(ds);
}

void Accum::AddSample(IDirect3DDevice9* dev) {
  if (failed_ || !scene_) return;
  IDirect3DSurface9 *rt = nullptr, *scene = nullptr, *next = nullptr;
  HRESULT hr = dev->GetRenderTarget(0, &rt);
  if (SUCCEEDED(hr)) hr = scene_->GetSurfaceLevel(0, &scene);
  if (SUCCEEDED(hr)) hr = acc_[cur_ ^ 1]->GetSurfaceLevel(0, &next);
  // Same size; StretchRect also resolves a multisampled backbuffer (FSAA).
  if (SUCCEEDED(hr)) hr = dev->StretchRect(rt, nullptr, scene, nullptr, D3DTEXF_NONE);
  if (SUCCEEDED(hr)) {
    const float k[4] = {1.0f / static_cast<float>(count_ + 1), 0, 0, 0};
    Draw(dev, next, psAccum_, acc_[cur_], scene_, k, kFullUv);
    cur_ ^= 1;
    ++count_;
  } else {
    Fail("AddSample", hr);
  }
  SafeRelease(rt);
  SafeRelease(scene);
  SafeRelease(next);
}

void Accum::Show(IDirect3DDevice9* dev) {
  if (failed_ || !scene_ || count_ == 0) return;
  IDirect3DSurface9* rt = nullptr;
  if (FAILED(dev->GetRenderTarget(0, &rt))) return;
  D3DSURFACE_DESC td;
  rt->GetDesc(&td);
  const bool half = width_ == 2 * static_cast<int>(td.Width) && height_ == 2 * static_cast<int>(td.Height);
  const float texel[4] = {1.0f / width_, 1.0f / height_, 0, 0};
  Draw(dev, rt, half ? psShow2x_ : psShow_, acc_[cur_], nullptr, texel, kFullUv);
  rt->Release();
}

void Accum::ShowRegion(IDirect3DDevice9* dev, const UvRect& uv) {
  if (failed_ || !scene_ || count_ == 0) return;
  IDirect3DSurface9* rt = nullptr;
  if (FAILED(dev->GetRenderTarget(0, &rt))) return;
  const float zero[4] = {};
  Draw(dev, rt, psShow_, acc_[cur_], nullptr, zero, uv);
  rt->Release();
}

void Accum::Hold(IDirect3DDevice9* dev) {
  if (failed_ || !scene_) return;
  HRESULT hr = S_OK;
  // Tile captures and the focus probe hold a frame: create the 8-bit copy on first use.
  if (!hold_ && FAILED(hr = dev->CreateTexture(width_, height_, 1, D3DUSAGE_RENDERTARGET, D3DFMT_X8R8G8B8,
                                               D3DPOOL_DEFAULT, &hold_, nullptr))) {
    Fail("Hold texture", hr);
    return;
  }
  CopyTarget(dev, hold_, "Hold");
}

void Accum::FreeHold() {
  SafeRelease(hold_);
  SafeRelease(kept_);
}

// Drawn with a shader, not StretchRect: the target may be the multisampled backbuffer (FSAA), which
// StretchRect cannot write from a non-multisampled source.
void Accum::ShowHold(IDirect3DDevice9* dev) {
  if (failed_ || !hold_) return;
  IDirect3DSurface9* rt = nullptr;
  if (FAILED(dev->GetRenderTarget(0, &rt))) return;
  const float zero[4] = {};
  Draw(dev, rt, psCopy_, hold_, nullptr, zero, kFullUv);
  rt->Release();
}

void Accum::Free() {
  Release();
  count_ = 0;
  failed_ = false;
}

void Accum::Fail(const char* what, long hr) {
  if (!failed_) U2LOG("%s: %s failed (hr=0x%08lX)", name_, what, hr);
  failed_ = true;
  Release();
}

void Accum::Release() {
  SafeRelease(scene_);
  SafeRelease(hold_);
  SafeRelease(kept_);
  SafeRelease(acc_[0]);
  SafeRelease(acc_[1]);
  SafeRelease(psAccum_);
  SafeRelease(psShow_);
  SafeRelease(psShow2x_);
  SafeRelease(psCopy_);
  SafeRelease(state_);
  width_ = height_ = 0;
}

}  // namespace photomode
